const PERSONAL_TTL_MS = 60_000;
const personalCache = new Map(); // userId -> { id, exp }
async function findPersonalEntityCached(reqUser) {
  const hit = personalCache.get(reqUser.id);
  if (hit && hit.exp > Date.now()) { return hit.id ? { id: hit.id } : null; }
  const row = await findPersonalEntity(reqUser);
  if (personalCache.size > 5000) { personalCache.clear(); }
  personalCache.set(reqUser.id, { id: row?.id || null, exp: Date.now() + PERSONAL_TTL_MS });
  return row;
}

